<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Bursar','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$itemId=filter_var($_POST['item_id']??null,FILTER_VALIDATE_INT);$type=(string)($_POST['movement_type']??'');$direction=(string)($_POST['direction']??'');$qty=$_POST['quantity']??null;$date=trim((string)($_POST['movement_on']??''));$reference=trim((string)($_POST['reference']??''));$destination=trim((string)($_POST['destination']??''));$reason=trim((string)($_POST['reason']??''));$cost=trim((string)($_POST['unit_cost']??''));$currency=(string)($_POST['currency']??'');$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$dateErrors=DateTimeImmutable::getLastErrors();$types=['Receipt','Issue','Write-off','Adjustment'];$validDate=$dt!==false&&$dt->format('Y-m-d')===$date&&($dateErrors===false||(!$dateErrors['warning_count']&&!$dateErrors['error_count']))&&$date<=date('Y-m-d');$validQty=is_numeric($qty)&&(float)$qty>0&&(float)$qty<=999999999.999;$validCost=$cost===''||(is_numeric($cost)&&(float)$cost>=0&&(float)$cost<=9999999999.99);$hasCost=$type==='Receipt'&&($cost!==''||$currency!=='');if($type!=='Receipt'){$cost='';$currency='';}
if(!$itemId||!in_array($type,$types,true)||!$validQty||!$validDate||strlen($reference)>100||strlen($destination)>160||strlen($reason)<3||strlen($reason)>255||!$validCost||($hasCost&&($type!=='Receipt'||$cost===''||!in_array($currency,['USD','ZiG'],true)))||($type==='Issue'&&$destination==='')||($type==='Adjustment'&&!in_array($direction,['Increase','Decrease'],true))){$_SESSION['error']='Check the stock movement type, quantity, date, reason and required issue/receipt details.';header('Location: ../?page=inventory');exit;}
$quantity=(float)$qty;$delta=in_array($type,['Issue','Write-off'],true)||($type==='Adjustment'&&$direction==='Decrease')?-$quantity:$quantity;$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT item_code,item_name,quantity_on_hand,active FROM school_inventory_items WHERE id=:id FOR UPDATE');$q->execute(['id'=>$itemId]);$item=$q->fetch();if(!$item||!(int)$item['active'])throw new DomainException('Choose an active stock item.');$current=(float)$item['quantity_on_hand'];if($current+$delta < -0.0005)throw new DomainException('There is not enough stock for this movement. The available quantity is '.number_format($current,3).' '.$item['item_name'].'.');$q=$pdo->prepare('UPDATE school_inventory_items SET quantity_on_hand=quantity_on_hand+:delta WHERE id=:id');$q->execute(['delta'=>number_format($delta,3,'.',''),'id'=>$itemId]);$q=$pdo->prepare('INSERT INTO school_inventory_movements(item_id,movement_type,movement_on,quantity_delta,unit_cost,currency,reference,destination,reason,recorded_by) VALUES(:item,:type,:date,:delta,:cost,:currency,:reference,:destination,:reason,:user)');$q->execute(['item'=>$itemId,'type'=>$type,'date'=>$date,'delta'=>number_format($delta,3,'.',''),'cost'=>$cost!==''?number_format((float)$cost,2,'.',''):null,'currency'=>$currency?:null,'reference'=>$reference?:null,'destination'=>$destination?:null,'reason'=>$reason,'user'=>$user['id']]);$movementId=(int)$pdo->lastInsertId();audit_log('inventory.movement_recorded','school_inventory_movements',$movementId,['item_code'=>$item['item_code'],'type'=>$type,'quantity_delta'=>number_format($delta,3,'.','')]);$pdo->commit();$_SESSION['notice']='Stock movement recorded; the balance has been updated.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Inventory movement failed: '.$e->getMessage());$_SESSION['error']='Could not save the stock movement. The balance was not 